// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface IERC20 {
    function transfer(address to, uint256 value) external returns (bool);
    function transferFrom(address from, address to, uint256 value) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

/**
 * @title RoyalJackpotVault
 * @notice Dedicated prize payout vault for Royal Jackpot winners.
 * Users claim their winnings via EIP-712 cryptographic signature issued by the backend signer.
 * Decoupled from Cyera MLM / Staking withdrawal contracts.
 */
contract RoyalJackpotVault {
    address public owner;
    address public pendingOwner;
    address public backendSigner;
    IERC20 public immutable usdt;
    bool public paused;

    // EIP-712 Domain Separator constants
    bytes32 private constant CLAIM_TYPEHASH = keccak256(
        "ClaimJackpotPrize(address recipient,uint256 amount,uint256 claimId,uint256 expiry)"
    );
    bytes32 public immutable DOMAIN_SEPARATOR;

    // Replay protection
    mapping(uint256 => bool) public isClaimExecuted;

    // Reentrancy guard
    uint256 private _status;
    uint256 private constant _NOT_ENTERED = 1;
    uint256 private constant _ENTERED = 2;

    uint256 public totalPrizesPaid;
    uint256 public totalClaimsCount;

    event PrizeClaimed(
        address indexed recipient,
        uint256 indexed claimId,
        uint256 amount,
        uint256 timestamp
    );
    event BackendSignerUpdated(address indexed previousSigner, address indexed newSigner);
    event OwnershipTransferStarted(address indexed previousOwner, address indexed newOwner);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
    event EmergencyWithdrawn(address indexed token, address indexed to, uint256 amount);
    event PausedStateChanged(bool isPaused);

    error ZeroAddress();
    error InvalidAmount();
    error SignatureExpired();
    error ClaimAlreadyExecuted();
    error InvalidSignature();
    error ContractPaused();
    error NotOwner();
    error NotPendingOwner();
    error TransferFailed();
    error ReentrancyGuardReentrantCall();
    error InsufficientVaultLiquidity();

    modifier onlyOwner() {
        if (msg.sender != owner) revert NotOwner();
        _;
    }

    modifier whenNotPaused() {
        if (paused) revert ContractPaused();
        _;
    }

    modifier nonReentrant() {
        if (_status == _ENTERED) revert ReentrancyGuardReentrantCall();
        _status = _ENTERED;
        _;
        _status = _NOT_ENTERED;
    }

    constructor(
        address _usdt,
        address _initialSigner,
        address _initialOwner
    ) {
        if (_usdt == address(0) || _initialSigner == address(0) || _initialOwner == address(0)) {
            revert ZeroAddress();
        }

        usdt = IERC20(_usdt);
        backendSigner = _initialSigner;
        owner = _initialOwner;
        _status = _NOT_ENTERED;

        DOMAIN_SEPARATOR = keccak256(
            abi.encode(
                keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"),
                keccak256(bytes("RoyalJackpotVault")),
                keccak256(bytes("1")),
                block.chainid,
                address(this)
            )
        );
    }

    /**
     * @notice Claim Royal Jackpot prize using authorized EIP-712 signature
     * @param amount USDT amount in Wei
     * @param claimId Unique claim ID generated by backend
     * @param expiry Timestamp after which signature is invalid
     * @param signature Cryptographic signature from backendSigner
     */
    function claimPrize(
        uint256 amount,
        uint256 claimId,
        uint256 expiry,
        bytes calldata signature
    ) external nonReentrant whenNotPaused {
        if (amount == 0) revert InvalidAmount();
        if (block.timestamp > expiry) revert SignatureExpired();
        if (isClaimExecuted[claimId]) revert ClaimAlreadyExecuted();

        // Check vault has sufficient USDT liquidity
        uint256 vaultBal = usdt.balanceOf(address(this));
        if (amount > vaultBal) revert InsufficientVaultLiquidity();

        // 1. Verify EIP-712 Signature
        bytes32 structHash = keccak256(
            abi.encode(
                CLAIM_TYPEHASH,
                msg.sender,
                amount,
                claimId,
                expiry
            )
        );

        bytes32 digest = keccak256(
            abi.encodePacked("\x19\x01", DOMAIN_SEPARATOR, structHash)
        );

        address recovered = _recoverSigner(digest, signature);
        if (recovered == address(0) || recovered != backendSigner) {
            revert InvalidSignature();
        }

        // 2. Mark as executed
        isClaimExecuted[claimId] = true;
        totalClaimsCount++;
        totalPrizesPaid += amount;

        // 3. Deliver USDT to user
        bool success = usdt.transfer(msg.sender, amount);
        if (!success) revert TransferFailed();

        emit PrizeClaimed(msg.sender, claimId, amount, block.timestamp);
    }

    function _recoverSigner(bytes32 hash, bytes memory sig) internal pure returns (address) {
        if (sig.length != 65) return address(0);

        bytes32 r;
        bytes32 s;
        uint8 v;

        assembly {
            r := mload(add(sig, 32))
            s := mload(add(sig, 64))
            v := byte(0, mload(add(sig, 96)))
        }

        if (v < 27) {
            v += 27;
        }

        if (v != 27 && v != 28) {
            return address(0);
        }

        return ecrecover(hash, v, r, s);
    }

    /**
     * @notice Emergency withdrawal by owner to maintain or rebalance liquidity
     */
    function emergencyWithdraw(address token, address to, uint256 amount) external onlyOwner nonReentrant {
        if (to == address(0)) revert ZeroAddress();
        bool success = IERC20(token).transfer(to, amount);
        if (!success) revert TransferFailed();
        emit EmergencyWithdrawn(token, to, amount);
    }

    function setBackendSigner(address _newSigner) external onlyOwner {
        if (_newSigner == address(0)) revert ZeroAddress();
        address old = backendSigner;
        backendSigner = _newSigner;
        emit BackendSignerUpdated(old, _newSigner);
    }

    function setPaused(bool _paused) external onlyOwner {
        paused = _paused;
        emit PausedStateChanged(_paused);
    }

    function transferOwnership(address newOwner) external onlyOwner {
        if (newOwner == address(0)) revert ZeroAddress();
        pendingOwner = newOwner;
        emit OwnershipTransferStarted(owner, newOwner);
    }

    function acceptOwnership() external {
        if (msg.sender != pendingOwner) revert NotPendingOwner();
        address oldOwner = owner;
        owner = pendingOwner;
        pendingOwner = address(0);
        emit OwnershipTransferred(oldOwner, owner);
    }
}

